function [ U, indicies, snrEstimate ] = hyperVca( M, q )
%HYPERVCA Vertex Component Analysis algorithm
%   hyperVca performs the vertex component analysis algorithm to find pure
% pixels in an HSI scene
%
% Usage
%   [ U, indicies, snrEstimate ] = hyperVca( M, q )
% Inputs
%   M - HSI data as 2D matrix (p x N).
%   q - Number of endmembers to find.
% Outputs
%   U - Matrix of endmembers (p x q).
%   indicies - Indicies of pure pixels in U
%   snrEstimate - SNR estimate of data [dB]
%
% References
%   J. M. P. Nascimento and J. M. B. Dias, �Vertex component analysis: A 
% fast algorithm to unmix hyperspectral data,? IEEE Transactions on 
% Geoscience and Remote Sensing, vol. 43, no. 4, apr 2005.

%Initialization.
N = size(M, 2);
L = size(M, 1);

% Compute SNR estimate.  Units are dB.
% Equation 13.
% Prefer using mean(X, dim).  I believe this should be faster than doing
% mean(X.') since matlab doesnt have to worry about the matrix
% transposition.
rMean = mean(M, 2);
RZeroMean = M - repmat(rMean, 1, N);
% This is essentially doing PCA here since we have zero mean data.
%  RZeroMean*RZeroMean.'/N -> covariance matrix estimate.
[Ud, Sd, Vd] = svds(RZeroMean*RZeroMean.'/N, q);
Rd = Ud.'*(RZeroMean);
P_R = sum(M(:).^2)/N;
P_Rp = sum(Rd(:).^2)/N + rMean.'*rMean;
SNR = abs(10*log10( (P_Rp - (q/L)*P_R) / (P_R - P_Rp) ));
snrEstimate = SNR;

fprintf('SNR estimate [dB]: %g\n', SNR);

% Determine which projection to use.
SNRth = 15 + 10*log(q) + 8;
%SNRth = 15 + 10*log(q);
if (SNR > SNRth) 
    d = q;
    [Ud, Sd, Vd] = svds((M*M.')/N, d);
    Xd = Ud.'*M;
    u = mean(Xd, 2);
    Y =  Xd ./ repmat( sum( Xd .* repmat(u,[1 N]) ) ,[d 1]);
    %for j=1:N
    %    Y(:,j) = Xd(:,j) / (Xd(:,j).'*u);
    %end
else
    d = q-1;
    r_bar = mean(M.').';
    Ud = pca(M, d);
    %Ud = Ud(:, 1:d);
    R_zeroMean = M - repmat(r_bar, 1, N);
    Xd = Ud.' * R_zeroMean;
    % Preallocate memory for speed.
    c = zeros(N, 1);
    for j=1:N
        c(j) = norm(Xd(:,j));
    end
    c = repmat(max(c), 1, N);
    Y = [Xd; c];
end
e_u = zeros(q, 1);
e_u(q) = 1;
A = zeros(q, q);
% idg - Doesnt match.
A(:, 1) = e_u;
I = eye(q);
k = zeros(N, 1);
for i=1:q
%     w = rand(q, 1);
     w =(1:q)';
    % idg - Oppurtunity for speed up here.
    tmpNumerator =  (I-A*pinv(A))*w;
    %f = ((I - A*pinv(A))*w) /(norm( tmpNumerator ));
    f = tmpNumerator / norm(tmpNumerator);

    v = f.'*Y;
    k = abs(v);
    [dummy, k] = max(k);
    A(:,i) = Y(:,k);
    indicies(i) = k;
end
if (SNR > SNRth)
    U = Ud*Xd(:,indicies);
else
    U = Ud*Xd(:,indicies) + repmat(r_bar, 1, q);
end
return;

function [U] = pca(X, d)
    N = size(X, 2);
    xMean = mean(X, 2);
    XZeroMean = X - repmat(xMean, 1, N);     
    [U,S,V] = svds((XZeroMean*XZeroMean.')/N, d);
return;

function [y, a] = simplex_project(x, E, D)
% SIMPLEX_PROJECT Project point onto simplex
%
% Syntax:
% [y, a] = simplex_project(x, E, D)
%
% This function projects the N-dimensional points in x onto the
% simplex spanned by the p points in E, and returns the projected points 
% and their barycentric coordinates with respect to the points in E. The
% projection is defined as the point within the simplex with minimal
% L2-distance.
% This is also the solution to the fully constrained least-squares problem
% x=E*a, with positivity and sum-to-one constraints imposed on a.
% 
% The algorithm is NOT guaranteed to find the optimal/true solution in all
% cases.
% 
% The algorithm used is described in 
%    Heylen R., Burazerovic D., Scheunders P., "Fully Constrained Least 
%    Squares Spectral Unmixing by Simplex Projection," Geoscience and
%    Remote Sensing, IEEE Transactions on, 49(11), 4112-4122, 2011.
%    doi: 10.1109/TGRS.2011.2155070
%    URL: http://ieeexplore.ieee.org/stamp/stamp.jsp?tp=&arnumber=5887410&isnumber=4358825
%
% Input:
% x : NxM vector, the M points to project
% E : Nxp matrix, the p points spanning the simplex
% D : (optional) pxp squared distance matrix of the endmembers
%
% Output:
% y : NxM vector, the projected points
% a : pxM vector, barycentric coordinates of y, so that y = E*a
%
%
% IMPORTANT NOTE: 
% For numerical stability, the input variables should not be too large. All
% inputs can for instance be rescaled to the interval [0,1] before use.
%
% Author: Rob Heylen
% Visionlab, University of Antwerp, January 2011


% Obtain matrix sizes
[N,M]=size(x);
p=size(E,2);

% The trivial zero-dimensional problem: projection onto a single point.
if p==1
    a=ones(1,M);
    y=E*a;
    return;
end

% Project points onto simplex plane, obtain barycentric coordinates.
x_orig=x;
[x,a]=plane_project(x,E);

% Test positivity and sum-to-one of barycentric coordinates, AND both
% tests.
d1=(sum(a(2:p,:)>=0,1))==(p-1); 
d2=sum(a(2:p,:),1)<=1;
d=d1.*d2; 

% Turn d into a list of all points not inside the simplex.
d=find(~d);
Md=length(d);

% If all points are inside the simplex, finish here
if Md==0
    y=E*a;
    return;
end

% Put the barycentric coordinates of points not in the simplex to zero.
a(:,d)=zeros(p,Md);

% We will need the squared distance matrix. If not yet given, calculate it.
if nargin==2
    D=squareform(pdist(E')).^2;
end

% Calculate the incenter via its barycentric coordinates.
ac=zeros(p,1);
for i=1:p
    range=[1:i-1 i+1:p];
    C_face=[D(range,range) ones(p-1,1); ones(1,p-1) 0];
    ac(i)=sqrt(det(C_face)*(-1)^(p-1));
end
c=E*(ac/sum(ac));

% Translation to put the incenter at the origin.
xc=x(:,d)-c*ones(1,Md);
Ec=E-c*ones(1,p);

% Loop over all vertices
for vertex=1:p
    range=[1:vertex-1 vertex+1:p];

    % Determine the points in the bissective cone of this vertex
    b=linsolve(Ec(:,range),xc);
    bi=prod(real(b>0),1);
    zi=find(bi); 

    % If there are points in this cone, recursive call
    if ~isempty(zi)
        xr=x_orig(:,d(zi));
        Er=E(:,range);
        [y,ar]=simplex_project(xr,Er,D(range,range));
        a(range,d(zi))=ar;

        % Remove treated points from list d
        zd=setdiff(1:Md,zi);
        d=d(zd);
        xc=xc(:,zd);
        Md=length(d);

    end

    if Md==0
        break; 
    end

end

% It is possible that due to numerical issues, the list d is not empty
% (e.g. a point that lies exactly on the boundary between two cones). These
% points could be treated here with an extra routine (still to do...).

% Optionally we could include a check here to see whether all the
% projections are correct. The points that were not correctly projected
% could then be treated via an alternative algorithm.

y=E*a;

end



function [y,a]=plane_project(x,E)
    [N,M]=size(x);
    p=size(E,2);
    a=zeros(p,M);
    ct=E(:,1);
    Ep=E(:,2:p)-ct*ones(1,p-1);
    a(2:p,:)=Ep\(x-ct*ones(1,M));
    a(1,:)=ones(1,M)-sum(a(2:p,:),1);
    y=E*a;
end

function imout=hyper2im(im,bands)
[m,n,p]=size(im);
if p==1
    im=double(im(:))';
    mu=mean(im);
    sigma=std(im);
    im=(im-mu)./(sigma+eps(im-mu));
    im=im*0.3;
    im=im+0.5;
    im=max(im,0);
    im=min(im,1);
    imout=reshape(im,[m,n]);
    imout=im2uint8(imout);
else
    if (nargin<2)
        bands=[1,round(p/2),p];
    end
    imout=zeros(m,n,3,'uint8');
    imout(:,:,1)=hyper2im(im(:,:,bands(1)));
    imout(:,:,2)=hyper2im(im(:,:,bands(2)));
    imout(:,:,3)=hyper2im(im(:,:,bands(3)));
end

function [dp,op,cle,auc,dp_20]= computeMetric(pd_boxes,ground_truth)
% % %%%%%%%%%%%%%%
% pd_boxes: resulted bouding boxes
% ground_truth: reference  bouding boxes
% dp: distance precision;
% op: overlapd precision;
% auc: area under curve of op;
% dp_20: distance precision @ 20 pixel;
% % %%%
distance_precision_threshold=1:50;
PASCAL_threshold=0.02:0.02:1;
op=zeros(1,length(PASCAL_threshold));
cle=zeros(1,length(PASCAL_threshold));
dp=zeros(1,length(distance_precision_threshold));
for j=1:length(distance_precision_threshold)
    [dp(j),op(j),cle(j)]= ...
        compute_performance_measures(pd_boxes, ground_truth,distance_precision_threshold(j),PASCAL_threshold(j));
end
auc=mean(op);
dp_20=dp(20);
end

function [distance_precision, PASCAL_precision, average_center_location_error] = ...
    compute_performance_measures(positions, ground_truth, distance_precision_threshold, PASCAL_threshold)

% [distance_precision, PASCAL_precision, average_center_location_error] = ...
%    compute_performance_measures(positions, ground_truth, distance_precision_threshold, PASCAL_threshold)
%
% For the given tracker output positions and ground truth it computes the:
% * Distance Precision at the specified threshold (20 pixels as default if
% omitted)
% * PASCAL Precision at the specified threshold (0.5 as default if omitted)
% * Average Center Location error (CLE).
%
% The tracker positions and ground truth must be Nx4-matrices where N is
% the number of time steps in the tracking. Each row has to be on the form
% [c1, c2, s1, s2] where (c1, c2) is the center coordinate and s1 and s2 
% are the size in the first and second dimension respectively (the order of 
% x and y does not matter here).

if nargin < 3 || isempty(distance_precision_threshold)
    distance_precision_threshold = 20;
end
if nargin < 4 || isempty(PASCAL_threshold)
    PASCAL_threshold = 0.5;
end

if size(positions,1) ~= size(ground_truth,1),
    disp('Could not calculate precisions, because the number of ground')
    disp('truth frames does not match the number of tracked frames.')
    return
end

ground_truth = [ground_truth(:,1:2) + (ground_truth(:,3:4) - 1) / 2 , ground_truth(:,3:4)];
positions = [positions(:,1:2) + (positions(:,3:4) - 1) / 2 , positions(:,3:4)];

%calculate distances to ground truth over all frames
distances = sqrt((positions(:,1) - ground_truth(:,1)).^2 + ...
    (positions(:,2) - ground_truth(:,2)).^2);
distances(isnan(distances)) = [];

%calculate distance precision
distance_precision = nnz(distances < distance_precision_threshold) / numel(distances);

%calculate average center location error (CLE)
average_center_location_error = mean(distances);

%calculate the overlap in each dimension
overlap_height = min(positions(:,1) + positions(:,3)/2, ground_truth(:,1) + ground_truth(:,3)/2) ...
    - max(positions(:,1) - positions(:,3)/2, ground_truth(:,1) - ground_truth(:,3)/2);
overlap_width = min(positions(:,2) + positions(:,4)/2, ground_truth(:,2) + ground_truth(:,4)/2) ...
    - max(positions(:,2) - positions(:,4)/2, ground_truth(:,2) - ground_truth(:,4)/2);

% if no overlap, set to zero
overlap_height(overlap_height < 0) = 0;
overlap_width(overlap_width < 0) = 0;

% remove NaN values (should not exist any)
valid_ind = ~isnan(overlap_height) & ~isnan(overlap_width);

% calculate area
overlap_area = overlap_height(valid_ind) .* overlap_width(valid_ind);
tracked_area = positions(valid_ind,3) .* positions(valid_ind,4);
ground_truth_area = ground_truth(valid_ind,3) .* ground_truth(valid_ind,4);

% calculate PASCAL overlaps
overlaps = overlap_area ./ (tracked_area + ground_truth_area - overlap_area);

% calculate PASCAL precision
PASCAL_precision = nnz(overlaps >= PASCAL_threshold) / numel(overlaps);
end

function [x,res_p,res_d] = clsunsal(M,y,varargin)

%% [x] = clsunsal_v1(M,y,varargin)
%
%  CLSUNSAL -> collaborative sparse unmixing via variable splitting and augmented
%  Lagrangian  
%
%% --------------- Description --------------------------------------------
%
%  CLSUNSAL solves the following l2-l1 optimization  problem 
%  [size(M) = (L,p); size(X) = (p,N)]; size(Y) = (L,N)]
%
%         min  (1/2) ||M X-Y||^2_F + lambda ||X||_{2,1}
%          X              
%
%  where ||X||_{2,1} = sum(sqrt(sum(X.^2),2))
% 
%    CONSTRAINTS ACCEPTED:
%
%    1) POSITIVITY:  X >= 0;
%    2) ADDONE:  sum(X) = ones(1,N);
%
%          
%
%% -------------------- Line of Attack  -----------------------------------
%
%  CLSUNSAL solves the above optimization problem by introducing a variable
%  splitting and then solving the resulting constrained optimization with
%  the augmented Lagrangian method of multipliers (ADMM). 
% 
% 
%         min  (1/2) ||M X-Y||^2_F + lambda ||V1||_{2,1} + i_+(V2)
%          X,Z              
%         subject to: sum(X) = ones(1,N)); V1 = X,  V2 = X;
%
%  Augmented Lagrangian (scaled version):
%
%       L(X,V1,V2,D1,D2) = (1/2) ||M X-Y||^2_F 
%                      + lambda ||V1||_{2,1} + mu/2||X-V1-D1||^2_F
%                      + i_+(V2) + mu/2||X-V2-D2||^2_F
%       
%  where D1 and D2 are the scaled Lagrange multipliers
%
%
%  ADMM:
%
%      do 
%        X  <-- arg min L(X,V1,V2,D1,D2)
%                    X,   s.t: sum(X) = ones(1,N));
%        V1  <-- arg min L(X,V1,V2,D1,D2)
%                     V1
%        V2  <-- arg min L(X,V1,V2,D1,D2)
%                     V2
%        D1  <-- D1 - (X-V1);
%        D2  <-- D2 - (X-V2);
%
%      while ~stop_rulde
%  
% For details see
%
% M. D. Iordache, J. M. Bioucas-Dias and A. Plaza. "Collaborative Sparse 
% Regression for Hyperspectral Unmixing",  IEEE Transactions on Geoscience 
% and Remote Sensing, 2013  (accepted).
% http://dx.doi.org/10.1109/TGRS.2013.2240001 
%
% NOTE: this version  differs from that  presented in the paper in two
% points: 
%     
%    a) the sum-to-one constraint is allowed
%
%    b) use just two spliting instead of the three proposed in the paper.
%       
% The version clsunsal_v1 implemts exactly the splitting scheme shwon in
% the paper
%
% ------------------------------------------------------------------------
%%  ===== Required inputs =============
%
%  M - [L(channels) x p(endmembers)] mixing matrix
%
%  y - matrix with  L(channels) x N(pixels).
%      each pixel is a linear mixture of p endmembers
%      signatures y = M*x + noise,
%
%      
%
%
%%  ====================== Optional inputs =============================
%
%  'AL_ITERS' - Minimum number of augmented Lagrangian iterations
%               Default: 100;
%               
%  lambda - regularization parameter. 
%
%
%  'POSITIVITY'  = {'yes', 'no'}; Enforces the positivity constraint: 
%                   X >= 0
%                   Default 'no'
%
%  'ADDONE'  = {'yes', 'no'}; Enforces the positivity constraint: X >= 0
%              Default 'no'
% 
%   'TOL'    - tolerance for the primal and  dual residuals 
%              Default = 1e-4; 
%
%
%  'verbose'   = {'yes', 'no'}; 
%                 'no' - work silently
%                 'yes' - display warnings
%                  Default 'no'
%        
%%  =========================== Outputs ==================================
%
% X  =  [pxN] estimated mixing matrix
%
%

%%
% ------------------------------------------------------------------
% Author: Jose Bioucas-Dias, 2012 
%
% 
% Modification: 
%
%     Jose Bioucas-Dias, July 2014 - corection of the projection onto R_+
%
%     

%% -------------------------------------------------------------------------
%
% Copyright (July, 2012):        Jos� Bioucas-Dias (bioucas@lx.it.pt)
%
% CLSUNSAL is distributed under the terms of
% the GNU General Public License 2.0.
%
% Permission to use, copy, modify, and distribute this software for
% any purpose without fee is hereby granted, provided that this entire
% notice is included in all copies of any software which is or includes
% a copy or modification of this software and in all copies of the
% supporting documentation for such software.
% This software is being provided "as is", without any express or
% implied warranty.  In particular, the authors do not make any
% representation or warranty of any kind concerning the merchantability
% of this software or its fitness for any particular purpose."
% ---------------------------------------------------------------------



%%
%--------------------------------------------------------------
% test for number of required parametres
%--------------------------------------------------------------
if (nargin-length(varargin)) ~= 2
    error('Wrong number of required parameters');
end
% mixing matrixsize
[LM,p] = size(M);
% data set size
[L,N] = size(y);
if (LM ~= L)
    error('mixing matrix M and data set y are inconsistent');
end
% if (L<p)
%     error('Insufficient number of columns in y');
% end


%%
%--------------------------------------------------------------
% Set the defaults for the optional parameters
%--------------------------------------------------------------
% maximum number of AL iteration
AL_iters = 1000;
% regularizatio parameter
lambda = 0.0;
% display only sunsal warnings
verbose = 'off';
% Positivity constraint
positivity = 'no';
% Sum-to-one constraint
addone = 'no';
% tolerance for the primal and dual residues
tol = 1e-4;
% initialization
x0 = 0;

%%
%--------------------------------------------------------------
% Local variables
%--------------------------------------------------------------


%--------------------------------------------------------------
% Read the optional parameters
%--------------------------------------------------------------
if (rem(length(varargin),2)==1)
    error('Optional parameters should always go by pairs');
else
    for i=1:2:(length(varargin)-1)
        switch upper(varargin{i})
            case 'AL_ITERS'
                AL_iters = round(varargin{i+1});
                if (AL_iters <= 0 )
                       error('AL_iters must a positive integer');
                end
            case 'LAMBDA'
                lambda = varargin{i+1};
                if lambda < 0
                       error('lambda must be positive');
                end
            case 'POSITIVITY'
                positivity = varargin{i+1};
            case 'ADDONE'
                addone = varargin{i+1};
            case 'TOL'
                tol = varargin{i+1};
            case 'VERBOSE'
                verbose = varargin{i+1};
            case 'X0'
                x0 = varargin{i+1};
                if (size(x0,1) ~= p) | (size(x0,1) ~= N)
                    error('initial X is  inconsistent with M or Y');
                end
            otherwise
                % Hmmm, something wrong with the parameter string
                error(['Unrecognized option: ''' varargin{i} '''']);
        end;
    end;
end


% compute mean norm
norm_y = sqrt(mean(mean(y.^2)));
% rescale M and Y and lambda
M = M/norm_y;
y = y/norm_y;
lambda = lambda/norm_y^2;

  

%%
%---------------------------------------------
% just least squares
%---------------------------------------------
if sum(sum(lambda == 0)) &&  strcmp(positivity,'no') && strcmp(addone,'no')
    z = pinv(M)*y;
    % primal and dual residues
    res_p = 0;
    res_d = 0;
    return
end
%---------------------------------------------
% least squares constrained (sum(x) = 1)
%---------------------------------------------
SMALL = 1e-12;
B = ones(1,p);
a = ones(1,N);

if  strcmp(addone,'yes') && strcmp(positivity,'no') 
    F = M'*M;
    % test if F is invertible
    if rcond(F) > SMALL
        % compute the solution explicitly
        IF = inv(F);
        z = IF*M'*y-IF*B'*inv(B*IF*B')*(B*IF*M'*y-a);
        % primal and dual residues
        res_p = 0;
        res_d = 0;
        return
    end
end


%%
%---------------------------------------------
%  Constants and initializations
%---------------------------------------------
mu_AL = 0.01;
mu = 10*mean(lambda(:)) + mu_AL;

%F = M'*M+mu*eye(p);
[UF,SF] = svd(M'*M);
sF = diag(SF);
IF = UF*diag(1./(sF+2*mu))*UF';
%IF = inv(F);
Aux = IF*B'*inv(B*IF*B');
x_aux = Aux*a;
IF1 = (IF-Aux*B*IF);


yy = M'*y;

%%
%---------------------------------------------
%  Initializations
%---------------------------------------------

% no intial solution supplied
if x0 == 0
    x= IF*M'*y;
end

% auxiliary variables
v1 = x;
v2 = x;

% scaled Lagrange Multipliers
d1  = 0*v1;
d2  = 0*v2;

%%
%---------------------------------------------
%  AL iterations - main body
%---------------------------------------------
tol1 = sqrt(N*p)*tol;
tol2 = sqrt(N*p)*tol;
i=1;
res_p = inf;
res_d = inf;
mu_changed = 0;
while (i <= AL_iters) && ((abs (res_p) > tol1) || (abs (res_d) > tol2)) 
    % save z to be used later
    if mod(i,10) == 1
        v10 = v1;
        v20 = v2;
    end
    % minimize with respect to v1
    v1 =  vector_soft_row(x-d1,lambda/mu);
    % minimize wrt v2
    v2 = x-d2;
    % teste for positivity
    if strcmp(positivity,'yes')
        v2 = max(0,v2);
    end
    % teste for sum-to-one 
    if strcmp(addone,'yes')
       x = IF1*(yy + mu*(v1+d1)+ mu*(v2+d2))+x_aux;
    else
       x = IF*(yy + mu*(v1+d1)+ mu*(v2+d2));
    end
    
    % Lagrange multipliers update
    d1 = d1 -(x-v1);
    d2 = d2 -(x-v2);

    % update mu so to keep primal and dual residuals whithin a factor of 10
    if mod(i,10) == 1
        % primal residue
        res_p = sqrt(norm(x-v1,'fro')^2 + norm(x-v2,'fro')^2);
        % dual residue
        res_d = mu*norm(v1-v10+v2-v20,'fro');
        if  strcmp(verbose,'yes')
            fprintf(' i = %f, res_p = %f, res_d = %f\n',i,res_p,res_d)
        end
        % update mu
        if res_p > 10*res_d
            mu = mu*2;
            d1 = d1/2;
            d2 = d2/2;
            mu_changed = 1;
        elseif res_d > 10*res_p
            mu = mu/2;
            d1 = d1*2;
            d2 = d2*2;
            mu_changed = 1;
        end
        if  mu_changed
           % update IF and IF1

           IF = UF*diag(1./(sF+2*mu))*UF';
           Aux = IF*B'*inv(B*IF*B');
           x_aux = Aux*a;
           IF1 = (IF-Aux*B*IF);
            mu_changed = 0;
        end
        
        
    end
    
    i=i+1;
        
   
       
end

    
 
